INSERT INTO glossary (term, type, explanation, url, related_terms) VALUES
  ('1844 Manuscripts Published', 'event', '**Location:** Moscow/Berlin | **People:** Karl Marx — Discovery and publication of Marx''s *Economic and Philosophic Manuscripts of 1844*. "Young Marx" — humanism, alienation, species-being — entered discourse. Influenced the Frankfurt School and generated debate about continuity vs. break between "young" and "mature" Marx.', NULL, NULL),
  ('Assassination of Patrice Lumumba', 'event', '**Location:** Katanga, Congo | **People:** Patrice Lumumba — CIA and Belgium eliminated Congo''s first democratically elected leader. Lumumba became a martyr of anti-imperialism, symbolizing the betrayal of African independence by Western powers and their local compradors.', NULL, NULL),
  ('Assassination of Thomas Sankara', 'event', '**Location:** Ouagadougou, Burkina Faso | **People:** Thomas Sankara, Blaise Compaoré — "Africa''s Che Guevara" killed by deputy Blaise Compaoré, backed by France. The "Upright Man" had vaccinated 2.5 million children in a week, planted 10 million trees, banned female genital mutilation, and challenged French neo-colonialism. His elimination ensured the continuation of Françafrique dependency.', NULL, NULL),
  ('Assassination of Trotsky', 'event', '**Location:** Coyoacán, Mexico | **People:** Leon Trotsky, Ramon Mercader — Ramon Mercader (NKVD agent) killed Trotsky with an ice axe. Last major Old Bolshevik eliminated. Trotsky''s final words to followers: "I am sure of the victory of the Fourth International. Go forward!"', NULL, NULL),
  ('Autumn Harvest Uprisings', 'event', '**Location:** Hunan, China | **People:** Mao Zedong — Mao led peasant insurrections in Hunan. After initial military failures, led surviving forces to the Jinggang Mountains — establishing the first rural revolutionary base area and pioneering peasant guerrilla warfare strategy.', NULL, NULL),
  ('Beijing Captured by CPC Forces', 'event', '**Location:** Beijing, China | **People:** Lin Biao, Fu Zuoyi — Former imperial capital taken after peaceful surrender of Nationalist garrison commander. Powerful symbolic victory.', NULL, NULL),
  ('Biennio Rosso Begins', 'event', '**Location:** Turin, Italy | **People:** Antonio Gramsci — Red Years in Italy. Turin workers occupy Fiat factories, run them through Factory Councils. Gramsci''s *L''Ordine Nuovo* leads the movement. The high point of Italian revolutionary activity.', NULL, NULL),
  ('Birth of Friedrich Engels', 'event', '**Location:** Barmen, Prussia | **People:** Friedrich Engels — Born into a wealthy textile manufacturing family. His father owned cotton mills in Germany and Manchester, giving Engels a direct view of industrial capitalism from both the factory floor and the boardroom. His *Condition of the Working Class in England* (1845) was one of the first systematic analyses of industrial poverty. Became Marx''s closest collaborator and financial supporter.', NULL, NULL),
  ('Birth of Karl Marx', 'event', '**Location:** Trier, Prussia | **People:** Karl Marx — Born into a middle-class family in the Prussian Rhineland, shaped by the French Revolution and Napoleonic occupation. Studied law and philosophy at Bonn and Berlin, encountered Hegelian philosophy, and developed the framework of historical materialism and the critique of political economy that transformed the workers'' movement worldwide.', NULL, NULL),
  ('Birth of Vladimir Lenin', 'event', '**Location:** Simbirsk, Russia | **People:** Vladimir Lenin — Born into a middle-class family. Brother Alexander executed in 1887 for plotting against the Tsar — the formative event of Lenin''s youth. Would develop the theory of the vanguard party, lead the Bolshevik faction, and direct the October Revolution.', NULL, NULL),
  ('Bologna Congress', 'event', '**Location:** Bologna, Italy | **People:** Amadeo Bordiga — At PSI congress, Bordiga formed the Abstentionist Communist Fraction — boycotting bourgeois parliamentary elections, demanding PSI align with the Comintern. Organizational precursor to the founding of PCd''I.', NULL, NULL),
  ('Bolshevik-Menshevik Split', 'event', '**Location:** London/Brussels | **People:** Vladimir Lenin, Julius Martov — RSDLP Second Congress. Immediate issue: definition of party membership. Deeper: nature of coming revolution, role of party, relationship to liberal bourgeoisie. Never healed — one of the most consequential organizational divisions in political history.', NULL, NULL),
  ('Bordiga Confronts Stalin', 'event', '**Location:** Moscow, Soviet Union | **People:** Amadeo Bordiga, Joseph Stalin — At ECCI Sixth Plenum, Bordiga declared the Russian Party must be subject to the International, not vice versa. The last significant open challenge to Stalin''s authority from within the Comintern''s own structures. Bordiga was subsequently marginalized.', NULL, NULL),
  ('Bordiga Founds Circolo Carlo Marx', 'event', '**Location:** Naples, Italy | **People:** Amadeo Bordiga — Revolutionary opposition to PSI reformism and Italy''s colonial war in Libya. Nucleus of the Italian Communist Left.', NULL, NULL),
  ('Bordiga''s Dialogue with Stalin', 'event', '**Location:** Italy | **People:** Amadeo Bordiga — Bordiga wrote *Economic and Social Structure of Russia Today*, proving the USSR was capitalist: wage labor, money, commodity exchange all remained. One of the earliest systematic analyses of the Soviet Union as state-capitalist.', NULL, NULL),
  ('Bordiga''s Lyons Theses', 'event', '**Location:** Italy | **People:** Amadeo Bordiga — Most comprehensive formal articulation of the Italian Left Communist position on party organization, the revolutionary process, and the relationship between national parties and the International. Remained the programmatic reference for the Italian Communist Left.', NULL, NULL),
  ('Bukharin Removed', 'event', '**Location:** Moscow, Soviet Union | **People:** Nikolai Bukharin, Joseph Stalin — Right Opposition crushed. Bukharin removed from Politburo. Stalin begins forced collectivization — resulting in millions of deaths from famine, particularly in Ukraine (Holodomor). All opposition to Stalin within the party now eliminated.', NULL, NULL),
  ('CPC Central Committee Evacuates Yan''an', 'event', '**Location:** Yan''an/Shaanxi, China | **People:** Mao Zedong, Zhou Enlai — Facing major Nationalist offensive, CPC evacuated Yan''an (base for nearly a decade). Mao established mobile headquarters in Shaanxi hills, demonstrating the party''s resilience and flexibility.', NULL, NULL),
  ('CPC Declaration on Resisting Japan', 'event', '**Location:** Yan''an, China | **People:** Mao Zedong — Called for broad national united front against Japanese aggression. Strategic shift from class war to national defense.', NULL, NULL),
  ('CPC Forces Cross the Yangtze', 'event', '**Location:** Nanjing, China | **People:** Mao Zedong — CPC crossed the Yangtze along a broad front. Nanjing, the Nationalist capital, captured April 23. Effective end of Nationalist resistance on the mainland.', NULL, NULL),
  ('Cambodian Genocide', 'event', '**Location:** Cambodia | **People:** Pol Pot — Khmer Rouge''s "Year Zero." Pol Pot attempted a primitive agrarian utopia by emptying cities. 1.5–2 million died from execution, starvation, and forced labor. A distorted ideology mixing Maoism with French existentialism, representing one of the 20th century''s worst atrocities.', NULL, NULL),
  ('Capital Volume I Published', 'event', '**Location:** Hamburg, Germany | **People:** Karl Marx — "The most terrible missile that has yet been hurled at the heads of the bourgeoisie." Central discovery: surplus value — profit derives from exploitation of labor. Exploitation is not an abuse of the system but its essential mechanism. Foundational text of Marxist political economy.', NULL, NULL),
  ('Chinese People''s Political Consultative Conference', 'event', '**Location:** Beijing, China | **People:** Mao Zedong, Zhou Enlai — Adopted the Common Programme as provisional constitution. Established the political framework for the People''s Republic.', NULL, NULL),
  ('Chinese Revolution', 'event', '**Location:** Beijing, China | **People:** Mao Zedong — "The Chinese people have stood up!" Mao proclaimed the People''s Republic from Tiananmen Gate. The world''s largest revolution by population — the peasantry surrounded the cities. Fundamentally altered the global balance of power.', NULL, NULL),
  ('Committee of Intesa Formed', 'event', '**Location:** Italy | **People:** Amadeo Bordiga — Italian Left organized internal opposition to Comintern''s bolshevisation directives and the transfer of party leadership away from Bordiga''s faction.', NULL, NULL),
  ('Communist Groups Established Across China', 'event', '**Location:** China | **People:** Chen Duxiu, Li Dazhao, Mao Zedong — Marxist study circles form in Shanghai, Beijing, Wuhan, Changsha, Guangzhou, and among Chinese students abroad. Organizational basis for the CPC founding.', NULL, NULL),
  ('Communist International Formally Dissolved', 'event', '**Location:** Moscow, Soviet Union | **People:** Joseph Stalin — Comintern dissolved by ECCI resolution. Stalin proposed dissolution ostensibly to demonstrate goodwill to Western Allies. Definitive end of the organizational framework of world revolution established by Lenin in 1919. National communist parties were now fully subordinated to Soviet foreign policy without even the pretense of an international structure.', NULL, NULL),
  ('Communist League Founded', 'event', '**Location:** London, England | **People:** Karl Marx, Friedrich Engels — Emerged from the League of the Just. Adopted "Working Men of All Countries, Unite!" Marx and Engels were commissioned to write the programme — *The Communist Manifesto*. First international organization explicitly committed to the communist programme.', NULL, NULL),
  ('Communist Manifesto Published', 'event', '**Location:** London, England | **People:** Karl Marx, Friedrich Engels — Most influential political pamphlet in history. "A spectre is haunting Europe — the spectre of communism." Analyzes the rise of the bourgeoisie, the nature of class struggle, and the historical mission of the proletariat. "The proletarians have nothing to lose but their chains. They have a world to win."', NULL, NULL),
  ('Communist Party of Italy Founded', 'event', '**Location:** Livorno, Italy | **People:** Amadeo Bordiga, Antonio Gramsci — Bordiga''s faction walks out of PSI congress singing the Internationale. Italian Comintern section born. Bordiga elected first general secretary.', NULL, NULL),
  ('Como Conference of PCd''I', 'event', '**Location:** Como, Italy | **People:** Amadeo Bordiga — Italian Left faction won majority on party direction despite Comintern pressure, demonstrating continued support for Bordiga''s positions within the party.', NULL, NULL),
  ('Conspiracy of Equals', 'event', '**Location:** Paris, France | **People:** Gracchus Babeuf, Sylvain Maréchal — First explicitly communist conspiracy in modern history. Babeuf demanded abolition of private property and a "community of goods." Betrayed and executed in 1797, but his ideas survived through Buonarroti''s 1828 book. Marx and Engels acknowledged Babeuf as a forerunner — the bourgeois revolution, once begun, could generate demands far beyond the bourgeoisie''s own programme.', NULL, NULL),
  ('Constituent Assembly Dissolved', 'event', '**Location:** Petrograd, Russia | **People:** Vladimir Lenin — Elected November 1917, met for one session. Bolsheviks (24% of vote) dissolved it, arguing soviet democracy was superior to bourgeois parliamentarism. One of the most debated acts of the revolution.', NULL, NULL),
  ('Cuban Revolution', 'event', '**Location:** Havana, Cuba | **People:** Fidel Castro, Che Guevara — 26th of July Movement triumphed. Batista fled. Socialism established 90 miles from the USA. The Cuban Revolution inspired national liberation movements across Latin America and Africa and became a focal point of Cold War confrontation.', NULL, NULL),
  ('Cultural Revolution Begins', 'event', '**Location:** China | **People:** Mao Zedong — "Bombard the Headquarters!" Mao mobilized Red Guards in a chaotic attempt to purge rivals and manage contradictions of state capitalism. "To rebel is justified!" The Cultural Revolution (1966–1976) devastated Chinese society, education, and culture, while claiming to defend revolutionary purity.', NULL, NULL),
  ('Das Kapital Volume II Published', 'event', '**Location:** Hamburg, Germany | **People:** Karl Marx, Friedrich Engels — Edited by Engels from Marx''s manuscripts. Analyzes circulation of capital, introduces Department I/II distinction, conditions for simple and expanded reproduction.', NULL, NULL),
  ('Das Kapital Volume III Published', 'event', '**Location:** Hamburg, Germany | **People:** Karl Marx, Friedrich Engels — Final volume. Analyzes the tendential fall in the rate of profit — capitalism''s own development undermines profitability, producing crises and ultimate historical limits. Published months before Engels''s death.', NULL, NULL),
  ('Death of Friedrich Engels', 'event', '**Location:** London, England | **People:** Friedrich Engels — Died of throat cancer at 74. Independent contributions: *Anti-Dühring*, *Origin of the Family, Private Property and the State*. Last direct link to founding generation of Marxism.', NULL, NULL),
  ('Death of Karl Marx', 'event', '**Location:** London, England | **People:** Karl Marx, Friedrich Engels — Died stateless at 64. Buried at Highgate Cemetery. Engels: "His name will endure through the ages." Left vast unfinished manuscripts including materials for Capital Vols. II & III.', NULL, NULL),
  ('Death of Lenin', 'event', '**Location:** Gorki, Soviet Russia | **People:** Vladimir Lenin, Joseph Stalin, Leon Trotsky — Lenin dies at 53 after strokes. His death triggered the power struggle that would define the Soviet Union''s trajectory. Stalin promoted "Socialism in One Country," breaking with internationalism. Body placed in mausoleum against the wishes of Lenin''s widow. Lenin''s "Testament" warning against Stalin was suppressed by the party leadership.', NULL, NULL),
  ('Decree on Peace', 'event', '**Location:** Petrograd, Russia | **People:** Vladimir Lenin — First act of the Soviet government. Called on all belligerents for immediate peace "without annexations or indemnities." Addressed to peoples over the heads of their rulers. Bolsheviks making good on their promise to end Russia''s participation in imperialist war.', NULL, NULL),
  ('Defeat of Napoleon at Waterloo', 'event', '**Location:** Waterloo, Belgium | **People:** Napoleon Bonaparte — Ended the Napoleonic Wars and ushered in the Congress of Vienna''s attempted Restoration. But the Napoleonic Code remained, embedding bourgeois property relations across Europe. Politically reactionary monarchies now presided over societies whose legal foundations had been permanently transformed — a contradiction generating the revolutions of 1830 and 1848.', NULL, NULL),
  ('Dissolution of the USSR', 'event', '**Location:** Moscow, Russia | **People:** Mikhail Gorbachev, Boris Yeltsin — Red flag lowered over the Kremlin. The Russian state-capitalist experiment, born from the degeneration of the October Revolution, ended — not through workers'' revolution but through the conversion of the bureaucratic ruling class into a private bourgeoisie. Transition to "bandit capitalism" under Yeltsin devastated the living standards of the Russian working class. End of an era — but not the end of the class struggle. **Total unique events: 161**', NULL, NULL),
  ('ECCI Orders Elimination of Bordiga Tendency', 'event', '**Location:** Moscow, Soviet Union | **People:** Amadeo Bordiga, Grigory Zinoviev — Comintern Executive ordered suppression of the Italian Left faction that had founded the Communist Party of Italy. Part of the broader pattern of Stalinization across the international communist movement.', NULL, NULL),
  ('Easter Rising', 'event', '**Location:** Dublin, Ireland | **People:** James Connolly — Irish Citizen Army — the only workers'' militia — rises against British rule. Connolly, a Marxist, saw it as simultaneously national liberation and a step toward workers'' power. Executed by firing squad strapped to a chair. Lenin defended the rising against critics who dismissed it as a "putsch."', NULL, NULL),
  ('Eleventh Plenum of ECCI', 'event', '**Location:** Moscow, Soviet Union — Reinforced "class against class" line, deepening sectarian orientation that isolated communist parties from potential allies against fascism.', NULL, NULL),
  ('Emergency Conference of CPC', 'event', '**Location:** Hankou, China | **People:** Mao Zedong, Qu Qiubai — Adopted new line of armed insurrection and agrarian revolution. Mao argued for mobilizing the peasantry as the main revolutionary force — a decisive strategic shift from urban to rural revolution.', NULL, NULL),
  ('Erfurt Program', 'event', '**Location:** Erfurt, Germany | **People:** Karl Kautsky — Written by Kautsky. Structural flaw: separated "maximum programme" (revolution) from "minimum programme" (reforms), allowing the party to focus entirely on reforms while revolution receded into an indefinite future.', NULL, NULL),
  ('Execution of Charles I', 'event', '**Location:** Whitehall, London | **People:** Oliver Cromwell, Charles I, Gerrard Winstanley — The English Revolution beheaded the divine right of kings and established parliamentary supremacy. Cromwell''s New Model Army defeated Royalist forces and brought Charles I to public trial — the first time a reigning monarch was tried and executed by his own subjects. Simultaneously, the Diggers under Gerrard Winstanley occupied St. George''s Hill demanding common ownership of land ("The Earth is a Common Treasury"), prefiguring communist ideas by two centuries.', NULL, NULL),
  ('Execution of Louis XVI', 'event', '**Location:** Paris, France | **People:** Louis XVI, Maximilien Robespierre — Marked the radicalization of the French Revolution. The Committee of Public Safety centralized power to defend the revolution against feudal Europe. The Terror (1793–94) remains debated: necessary defense or prototype of revolutionary authoritarianism. The execution sent a clear message to every monarchy in Europe.', NULL, NULL)
INSERT INTO glossary (term, type, explanation, url, related_terms) VALUES
  ('Failed German October', 'event', '**Location:** Hamburg, Germany | **People:** Ernst Thälmann — KPD planned insurrection, called off last minute. Only Hamburg rises under Thälmann, is suppressed. Revolutionary wave recedes in Europe. Beginning of the end of the post-1917 revolutionary period.', NULL, NULL),
  ('Fall of Saigon', 'event', '**Location:** Saigon, Vietnam | **People:** Ho Chi Minh — Vietnam unified after decades of war. The most powerful military machine in history defeated by a peasant army. The fall of Saigon marked the end of the American war in Vietnam and the limits of US imperial power.', NULL, NULL),
  ('Fall of the Paris Commune', 'event', '**Location:** Paris, France — Crushed during *Semaine Sanglante*. ~20,000 Communards killed or executed. Thousands deported to New Caledonia. The Commune''s martyrs became sacred figures. Every subsequent revolutionary movement drew lessons from both its achievements and its defeat.', NULL, NULL),
  ('February Revolution', 'event', '**Location:** Petrograd, Russia | **People:** Nicholas II — Female textile workers strike on International Women''s Day. Soldiers join. Tsar abdicates — 300+ years of Romanov rule ended. "Dual Power" emerges: Provisional Government vs. Petrograd Soviet. Unstable equilibrium resolved by October.', NULL, NULL),
  ('Fifth Congress of Comintern', 'event', '**Location:** Moscow, Soviet Union | **People:** Grigory Zinoviev, Amadeo Bordiga — Adopted "Bolshevisation" — requiring all parties to reorganize on factory cells rather than territorial sections. Criticized by Italian Left as bureaucratic imposition severing parties from their organic traditions. Marked growing Stalinization of the Comintern.', NULL, NULL),
  ('Finnish Civil War', 'event', '**Location:** Finland | **People:** Carl Gustaf Mannerheim — Social Democratic Reds vs. conservative Whites with German military support. ~30,000 Reds died, many in camps. One of the first counter-revolutionary victories post-October — demonstrated bourgeoisie would fight with extreme brutality to prevent spread of soviet power.', NULL, NULL),
  ('First Capitalist Crisis', 'event', '**Location:** England — First truly international capitalist economic crisis. Began with a speculative bubble collapse in Latin American stocks, spread across Europe and Latin America. Demonstrated that capitalism''s instability is systemic, not accidental — confirming what became central to Marxist economics: periodic crises of overproduction driven by the contradiction between socialized production and private appropriation.', NULL, NULL),
  ('First Congress of Chinese Socialist Youth League', 'event', '**Location:** Guangzhou, China — Established organizational framework for recruiting young people into the communist movement in China.', NULL, NULL),
  ('First English Capital', 'event', '**Location:** London, England | **People:** Karl Marx, Friedrich Engels — Moore/Aveling translation supervised by Engels. Brought Marx''s critique to the heartland of industrial capitalism.', NULL, NULL),
  ('First International Dissolved', 'event', '**Location:** Philadelphia, USA | **People:** Karl Marx, Friedrich Engels — IWA formally dissolved. Despite organizational demise, it established the principle of international working-class solidarity and demonstrated that the class struggle is inherently international.', NULL, NULL),
  ('First International Founded', 'event', '**Location:** London, England | **People:** Karl Marx — International Workingmen''s Association (IWA) founded at St. Martin''s Hall. Marx delivered the Inaugural Address: "The emancipation of the working classes must be conquered by the working classes themselves." First sustained attempt to organize the workers'' movement internationally.', NULL, NULL),
  ('First Japanese Translation of Manifesto', 'event', '**Location:** Japan | **People:** Sakai Toshihiko, Kotoku Shusui — Published in *Heimin Shimbun*. Marxism reaches Japan — part of its transformation into a truly global movement.', NULL, NULL),
  ('First National Congress of Chinese Communist Party', 'event', '**Location:** Shanghai/Jiaxing, China | **People:** Mao Zedong, Chen Duxiu, Li Dazhao — CPC founded. 13 delegates representing ~57 members, meeting secretly in Shanghai''s French Concession, later moving to a boat to avoid police. Beginning of one of history''s most consequential political organizations.', NULL, NULL),
  ('First National Labour Conference', 'event', '**Location:** Guangzhou, China — First attempt to coordinate the Chinese labor movement nationally under communist influence.', NULL, NULL),
  ('First Russian Revolution', 'event', '**Location:** St. Petersburg, Russia | **People:** Vladimir Lenin, Leon Trotsky — Bloody Sunday triggered strikes, peasant uprisings, military mutinies, and spontaneous formation of soviets. Trotsky chaired St. Petersburg Soviet. Lenin called it a "dress rehearsal" for 1917.', NULL, NULL),
  ('First Russian Translation of Manifesto', 'event', '**Location:** Geneva, Switzerland | **People:** Georgi Plekhanov, Karl Marx — Marx''s preface addresses whether Russia can bypass capitalism via the peasant commune (*obshchina*) — conditionally yes, if supported by Western revolution. Most explicit engagement with uneven development.', NULL, NULL),
  ('Fourth Congress of Comintern', 'event', '**Location:** Moscow, Soviet Russia | **People:** Vladimir Lenin, Amadeo Bordiga, Leon Trotsky — Formally adopted United Front tactic. Bordiga presented report on fascism in Italy, analyzing its class character. Last congress Lenin was able to attend.', NULL, NULL),
  ('Franco Wins Spanish Civil War', 'event', '**Location:** Spain | **People:** Francisco Franco — Republic falls. Hundreds of thousands flee into exile. Revolution definitively crushed. Last hope of stopping fascism through popular resistance extinguished.', NULL, NULL),
  ('Full-Scale Chinese Civil War Resumes', 'event', '**Location:** China | **People:** Mao Zedong, Chiang Kai-shek — Resumed after breakdown of American-mediated ceasefire. Nationalists initially held significant advantage in manpower and equipment, but CPC''s land reform programme won massive peasant support.', NULL, NULL),
  ('German Revolution', 'event', '**Location:** Germany | **People:** Rosa Luxemburg, Karl Liebknecht, Gustav Noske — Sailors mutiny in Kiel. Workers'' and soldiers'' councils form across Germany. Kaiser abdicates. SPD takes power to stop the revolution. Noske: "Someone must be the bloodhound."', NULL, NULL),
  ('Germany Invades Soviet Union', 'event', '**Location:** Soviet Union | **People:** Adolf Hitler, Joseph Stalin — Operation Barbarossa — the largest military invasion in history. 3.8 million troops along a 2,900-kilometer front. The Eastern Front became the decisive theater of WWII, where the Wehrmacht was ultimately ground down and destroyed. The Soviet Union suffered 27 million dead — the greatest sacrifice of any nation in the war.', NULL, NULL),
  ('Global Economic Crisis of 1857', 'event', '**Location:** Global | **People:** Karl Marx — First truly worldwide crisis. Marx saw it as a potential revolutionary trigger and intensified his economic studies, producing the *Grundrisse* notebooks (1857–58) — crucial preparatory stage for *Capital*.', NULL, NULL),
  ('Gotha Congress', 'event', '**Location:** Gotha, Germany | **People:** Karl Marx, Ferdinand Lassalle — United German socialism (SDAP + ADAV) into SAPD (later SPD). Marx''s *Critique of the Gotha Programme* attacks reformist slogans and argues for the "revolutionary dictatorship of the proletariat." Published 1891 by Engels against SPD leadership wishes.', NULL, NULL),
  ('Grundrisse Published', 'event', '**Location:** Moscow, Soviet Union | **People:** Karl Marx — Limited Moscow edition of Marx''s 1857–58 notebooks. Only became widely known in the West in the 1970s. Revolutionized understanding of Marx''s value theory — contains his most extensive treatment of abstract labor, money, and the "fragment on machines."', NULL, NULL),
  ('Hague Congress of the First International', 'event', '**Location:** The Hague, Netherlands | **People:** Karl Marx, Mikhail Bakunin, Friedrich Engels — Most contentious congress in IWA history. General Council relocated to New York; anarchist faction under Bakunin expelled. The Marx-Bakunin split centered on political action vs. immediate abolition of the state, and centralized party vs. federalist communes. Division persists to this day.', NULL, NULL),
  ('Haitian Revolution Begins', 'event', '**Location:** Saint-Domingue (Haiti) | **People:** Toussaint Louverture — The only successful large-scale slave revolt in history. Toussaint Louverture emerged as military and political leader, defeating French, Spanish, and British forces. The revolution forced the Enlightenment to confront its racial hypocrisy: "Rights of Man" had never been intended for the Black slave. It permanently altered the politics of slavery, colonialism, and race in the Atlantic world.', NULL, NULL),
  ('Haymarket Affair', 'event', '**Location:** Chicago, USA | **People:** Albert Parsons, August Spies — Origin of International Workers'' Day (May Day). Bomb thrown at police during eight-hour day rally; eight anarchist leaders convicted in political trial, four hanged. Second International designated May 1st as annual demonstration day in their honor.', NULL, NULL),
  ('Hitler Takes Power', 'event', '**Location:** Berlin, Germany | **People:** Adolf Hitler, Ernst Thälmann — KPD, following Stalin''s "Third Period" theory, refused united front with SPD against Nazism ("After Hitler, us!"). The strongest Communist Party in Europe outside the USSR was destroyed without resistance. Thälmann arrested, later executed in Buchenwald. The most catastrophic consequence of Stalinist sectarianism.', NULL, NULL),
  ('Hong Kong Seamen''s Strike', 'event', '**Location:** Hong Kong, China — Major strike by Chinese maritime workers demanding wage increases. Lasted until March. Demonstrated growing working-class militancy and influence of the nascent communist movement on Chinese labor.', NULL, NULL),
  ('Hungarian Revolution', 'event', '**Location:** Budapest, Hungary | **People:** Imre Nagy — Workers'' councils demanded "Socialism without Russians." Crushed by Soviet tanks. 2,500 Hungarians died defending the revolution. Demonstrated that opposition to bureaucratic rule could take the form of workers'' self-organization — soviets against the "Soviet" state.', NULL, NULL),
  ('Hungarian Soviet Republic', 'event', '**Location:** Budapest, Hungary | **People:** Béla Kun — 133 days of red power (March–August). Béla Kun leads short-lived communist state. Falls to Romanian invasion and internal counter-revolution. Demonstrated both the possibility and fragility of revolution outside Russia.', NULL, NULL),
  ('Imola Conference of the Italian Left', 'event', '**Location:** Imola, Italy | **People:** Amadeo Bordiga — Bordiga''s Abstentionist Fraction merged with other left currents to form the Unified Communist Fraction, preparing the ground for the founding of the PCd''I at Livorno two months later.', NULL, NULL),
  ('Imperialism, the Highest Stage of Capitalism', 'event', '**Location:** Petrograd, Russia | **People:** Vladimir Lenin — Analyzes capitalism''s development into monopoly capitalism and imperialism. WWI was not accidental but inevitable. Imperialism generates "super-profits" from colonial exploitation, allowing the bourgeoisie to bribe an "aristocracy of labour." Standard Marxist analysis of the world system.', NULL, NULL),
  ('Independence of Haiti', 'event', '**Location:** Haiti | **People:** Jean-Jacques Dessalines, Toussaint Louverture — Dessalines ripped the white stripe from the French tricolor. Haiti became the first independent Black republic. France demanded massive "reparations" for lost slave property — a debt Haiti paid until 1947, crippling its development. Haiti proved enslaved peoples could liberate themselves through organized action.', NULL, NULL),
  ('Internationalist Communist Party of Italy Founded', 'event', '**Location:** Italy | **People:** Onorato Damen, Bruno Maffi — PCInt (Partito Comunista Internazionalista) established by Damen, Maffi, and returning exiles. Sought to continue the Italian Communist Left tradition outside the Stalinist framework. Re-established left communist organizational presence in Italy.', NULL, NULL),
  ('Italian Left Fraction Formed in Exile', 'event', '**Location:** Pantin, France | **People:** Amadeo Bordiga — Members of the Italian Communist Left in emigration formed the Left Fraction, continuing to uphold Italian Left positions against the Stalinized Comintern. Published theoretical journals and maintained organizational continuity through the exile years.', NULL, NULL),
  ('Japan Attacks Pearl Harbor', 'event', '**Location:** Pearl Harbor, Hawaii — Surprise attack on the US naval base brought the United States into WWII, transforming it into a truly global conflict. The Pacific War would end with the atomic bombings of Hiroshima and Nagasaki.', NULL, NULL),
  ('Japan Surrenders', 'event', '**Location:** Tokyo, Japan | **People:** Hirohito — Unconditional surrender following atomic bombings of Hiroshima and Nagasaki and Soviet declaration of war. End of WWII in Asia. Created conditions for the final phase of the Chinese Civil War.', NULL, NULL),
  ('July Days Uprising', 'event', '**Location:** Petrograd, Russia | **People:** Vladimir Lenin — Spontaneous armed demonstrations demanding "All Power to the Soviets." Suppressed by Provisional Government. Lenin goes into hiding in Finland. Taught Bolsheviks that insurrection requires careful preparation and soviet majority — conditions met by October.', NULL, NULL),
  ('June Days Uprising', 'event', '**Location:** Paris, France — Definitive class rupture of 1848. Workers rose when the government dissolved the National Workshops. ~3,000 killed, 1,500 summarily executed, 12,000 arrested. Marx called it "the first great battle between the two great classes of modern society." Bourgeoisie and proletariat parted ways definitively.', NULL, NULL),
  ('Kienthal Conference', 'event', '**Location:** Kienthal, Switzerland | **People:** Vladimir Lenin, Robert Grimm — Second Zimmerwald conference. More militant manifesto: explicitly called on socialist deputies to vote against war credits and break with national unity governments. Reflected growing radicalization.', NULL, NULL),
  ('Kornilov Affair', 'event', '**Location:** Petrograd, Russia | **People:** Vladimir Lenin, Lavr Kornilov — General Kornilov attempts military coup. Bolsheviks organize defense, arm Red Guards. Coup collapses; Bolsheviks emerge as defenders of the revolution. Win majorities in Petrograd and Moscow soviets for the first time.', NULL, NULL),
  ('Kronstadt Rebellion', 'event', '**Location:** Kronstadt, Soviet Russia | **People:** Vladimir Lenin, Leon Trotsky — Sailors demand "Soviets without Bolsheviks." Suppressed by Red Army. Exposed contradictions of War Communism and the growing gap between the Bolshevik state and the working class it claimed to represent.', NULL, NULL),
  ('Lenin Returns', 'event', '**Location:** Petrograd, Russia | **People:** Vladimir Lenin — Returns via "sealed train." Issues April Theses at Finland Station: no support for Provisional Government, all power to the Soviets, end the war, nationalize land. Rejects orthodox position that Russia must complete bourgeois revolution first. Initially opposed by most Bolshevik leaders; prevailed within weeks.', NULL, NULL),
  ('Long March Begins', 'event', '**Location:** Jiangxi, China | **People:** Mao Zedong, Zhou Enlai, Zhu De — ~86,000 Red Army soldiers broke through Nationalist encirclement in the Fifth Encirclement Campaign. The march would cover ~9,000 kilometers over one year. Defining experience of the CPC leadership generation.', NULL, NULL),
  ('Long March Concludes', 'event', '**Location:** Yan''an, China | **People:** Mao Zedong — Surviving forces arrived in Yan''an, Shaanxi. Of ~86,000 who began, only ~8,000 completed the march. Yan''an served as CPC base for the next decade.', NULL, NULL),
  ('Lyon Congress of PCd''I', 'event', '**Location:** Lyon, France | **People:** Amadeo Bordiga, Antonio Gramsci, Palmiro Togliatti — Party leadership transferred from Bordiga''s faction to the centre group led by Gramsci and Togliatti, in line with Comintern directives. Italian Left presented its theses but was defeated. Decisive turning point for Italian communism.', NULL, NULL),
  ('Manifesto Translated to Chinese', 'event', '**Location:** China | **People:** Chen Wangdao, Chen Duxiu — Chen Wangdao translates the Manifesto — supposedly eating ink by mistake in his cold shed. Seed for the Chinese Communist Party planted.', NULL, NULL),
  ('Mao Arrives in Chongqing for Negotiations', 'event', '**Location:** Chongqing, China | **People:** Mao Zedong, Chiang Kai-shek — First Mao-Chiang meeting since the war. Despite signing the "Double Tenth Agreement" (Oct 10), negotiations failed to prevent resumption of full-scale civil war.', NULL, NULL),
  ('Marco Polo Bridge Incident', 'event', '**Location:** Beijing, China — Skirmish between Chinese and Japanese troops escalated into full-scale war. Beginning of the Second Sino-Japanese War, merging into World War II.', NULL, NULL)
INSERT INTO glossary (term, type, explanation, url, related_terms) VALUES
  ('Marx Marries Jenny von Westphalen', 'event', '**Location:** Kreuznach, Prussia | **People:** Karl Marx, Jenny von Westphalen — Seven-year engagement. Marriage marked by deep devotion alongside extreme material hardship. Jenny shared Marx''s political convictions, copied manuscripts, and maintained political correspondence. Her sacrifice was essential to Marx''s ability to continue his theoretical work.', NULL, NULL),
  ('Marx Writes The German Ideology', 'event', '**Location:** Brussels, Belgium | **People:** Karl Marx, Friedrich Engels — First systematic formulation of historical materialism. "The ruling ideas of each age have ever been the ideas of its ruling class." Unpublished in their lifetime — Marx said it served "self-clarification." Full text published 1932, transforming understanding of Marx''s thought.', NULL, NULL),
  ('Marx and Engels Meet in Paris', 'event', '**Location:** Paris, France | **People:** Karl Marx, Friedrich Engels — Met at the Café de la Régence. Discovered they had arrived at identical conclusions independently — Marx through philosophy and political economy, Engels through observation of English industrial conditions. Initiated the most important intellectual partnership in the history of the workers'' movement.', NULL, NULL),
  ('Marxism and the National Question', 'event', '**Location:** Vienna, Austria-Hungary | **People:** Joseph Stalin, Vladimir Lenin — Stalin''s systematic treatment of the national question, commissioned by Lenin. Against Austro-Marxist "national-cultural autonomy." Established Stalin''s reputation on the national question.', NULL, NULL),
  ('May ''68 in France', 'event', '**Location:** Paris, France | **People:** Daniel Cohn-Bendit — Students occupied the Sorbonne; 10 million workers joined a general strike — the largest in French history. "Be realistic, demand the impossible!" The PCF (French Communist Party) helped de-escalate the strike to save the Gaullist state, demonstrating the counter-revolutionary role of Stalinist parties in the advanced capitalist countries.', NULL, NULL),
  ('May Days in Barcelona', 'event', '**Location:** Barcelona, Spain | **People:** Andreu Nin, George Orwell — PSUC (Stalinist) and Republican police crush the revolution within the republic. Andreu Nin (POUM leader) tortured and killed by Soviet agents. Orwell narrowly escapes. Demonstrated that Stalinism was prepared to destroy the revolution to maintain control.', NULL, NULL),
  ('May Fourth Movement', 'event', '**Location:** Beijing, China | **People:** Chen Duxiu, Li Dazhao — Students demonstrated against Treaty of Versailles transferring German concessions in Shandong to Japan. Spread nationwide, catalyzing broad intellectual and political awakening. Created conditions for the spread of Marxism in China.', NULL, NULL),
  ('NEP Introduced', 'event', '**Location:** Soviet Russia | **People:** Vladimir Lenin — New Economic Policy allows limited market relations: "One step backward, two steps forward." Retreat from War Communism necessitated by economic collapse. Introduced limited private trade and small-scale enterprise while maintaining state ownership of commanding heights.', NULL, NULL),
  ('Nanchang Uprising', 'event', '**Location:** Nanchang, China | **People:** Zhou Enlai, He Long, Zhu De — Beginning of CPC armed struggle. Forces under Zhou Enlai launched armed uprising. Rebels forced to retreat within days, but the event is celebrated as the founding of the Chinese Red Army. August 1 remains PRC Army Day.', NULL, NULL),
  ('Nanjing Massacre', 'event', '**Location:** Nanjing, China — Japanese forces captured Nanjing. In the following weeks, mass killings, rape, and destruction. Estimates: tens of thousands to 300,000+ killed. One of the worst atrocities of the 20th century.', NULL, NULL),
  ('PSI Milan Congress', 'event', '**Location:** Milan, Italy | **People:** Amadeo Bordiga — Left tendency opposed parliamentary alliances with bourgeois parties. Bordiga continued developing anti-electoralist positions.', NULL, NULL),
  ('PSI Reggio Emilia Congress', 'event', '**Location:** Reggio Emilia, Italy | **People:** Amadeo Bordiga, Benito Mussolini — Intransigent Revolutionary Fraction formed. Both Bordiga and young Mussolini (then still socialist) associated — later radically divergent paths.', NULL, NULL),
  ('Prague Conference', 'event', '**Location:** Prague, Austria-Hungary | **People:** Vladimir Lenin — Bolsheviks formally constitute as independent party. Organizational basis for October laid.', NULL, NULL),
  ('RSDLP Founded', 'event', '**Location:** Minsk, Russian Empire | **People:** Vladimir Lenin — Nine delegates in a small wooden house; most arrested shortly after. Inauspicious beginning of the party that would make the October Revolution.', NULL, NULL),
  ('SDAP Founded in Eisenach', 'event', '**Location:** Eisenach, Germany | **People:** August Bebel, Wilhelm Liebknecht — First mass political party based on Marxist principles. Distinguished from Lassalle''s ADAV by internationalism and rejection of alliance with Bismarck. Affiliated with the First International. Model for socialist parties across Europe.', NULL, NULL),
  ('Second Congress of Comintern', 'event', '**Location:** Moscow, Soviet Russia | **People:** Vladimir Lenin — Lenin presents 21 Conditions for membership, enforcing split with reformists. Comintern defines itself against social democracy. Only parties accepting centralized discipline and revolutionary programme admitted.', NULL, NULL),
  ('Second International Amsterdam Congress', 'event', '**Location:** Amsterdam, Netherlands | **People:** Jean Jaurès, August Bebel — Major debate on "ministerialism" — whether socialists should join bourgeois governments. Adopted resolution against. Foreshadowed the collaboration vs. revolution question of 1914.', NULL, NULL),
  ('Second International Basel Congress', 'event', '**Location:** Basel, Switzerland | **People:** Jean Jaurès, Rosa Luxemburg — Emergency congress on Balkan Wars and European war threat. Basel Manifesto: determination to prevent war and use conflict to accelerate capitalism''s fall. Less than two years later, most parties that voted for it would support the war.', NULL, NULL),
  ('Second International Brussels Congress', 'event', '**Location:** Brussels, Belgium | **People:** Friedrich Engels — Adopted resolution affirming necessity of political action by the working class. Further consolidated parliamentary socialist strategy.', NULL, NULL),
  ('Second International Copenhagen Congress', 'event', '**Location:** Copenhagen, Denmark | **People:** Clara Zetkin — Clara Zetkin proposed International Women''s Day (8 March), adopted by congress. Women textile workers striking on that date in 1917 would trigger the February Revolution.', NULL, NULL),
  ('Second International Founded', 'event', '**Location:** Paris, France | **People:** Friedrich Engels — Founded on centenary of the French Revolution. United socialist and labor parties globally. Adopted May Day. Under it, mass parties grew enormously. But reformism, parliamentarism, and trade union bureaucracy undermined revolutionary commitment. Collapsed in August 1914.', NULL, NULL),
  ('Second International Stuttgart Congress', 'event', '**Location:** Stuttgart, Germany | **People:** Rosa Luxemburg, Vladimir Lenin, August Bebel — Anti-militarism resolution: socialists must "utilize the crisis created by war to hasten the downfall of capitalist class rule." Luxemburg and Lenin amended it. The resolution became the measure of betrayal in 1914.', NULL, NULL),
  ('Second International Zurich Congress', 'event', '**Location:** Zurich, Switzerland | **People:** Friedrich Engels — Formally excluded anarchists, cementing commitment to political party organization. Engels attended — one of his last major public appearances.', NULL, NULL),
  ('Second National Congress of CPC', 'event', '**Location:** Shanghai, China | **People:** Chen Duxiu — Adopted minimum programme (anti-imperialism, anti-feudalism, democratic republic) and maximum programme (socialism/communism). Formally voted to join the Comintern.', NULL, NULL),
  ('Second United Front Formally Announced', 'event', '**Location:** China | **People:** Chiang Kai-shek, Mao Zedong, Zhou Enlai — KMT-CPC cooperation against Japan. Red Army reorganized as Eighth Route Army under nominal Nationalist command. Uneasy alliance that would collapse after the defeat of Japan.', NULL, NULL),
  ('Secretariat of Chinese Labour Organization', 'event', '**Location:** Shanghai, China | **People:** Zhang Guotao — First nationwide labor organizing body under CPC leadership. Beginning of systematic communist-led labor organizing in China.', NULL, NULL),
  ('Seventh Congress of Comintern', 'event', '**Location:** Moscow, Soviet Union | **People:** Georgi Dimitrov, Joseph Stalin — Final regular Comintern congress. Adopted Popular Front policy — alliances with bourgeois democratic parties against fascism. Dramatic reversal of Third Period line. Dimitrov presented main report.', NULL, NULL),
  ('Seventh Enlarged Plenum of ECCI', 'event', '**Location:** Moscow, Soviet Union | **People:** Joseph Stalin, Amadeo Bordiga — Stalin formally presented "Socialism in One Country" — decisive break with the internationalist orientation of the early Comintern. PCd''I delegation expelled from Comintern leadership structures. Marked the definitive Stalinization of the International.', NULL, NULL),
  ('Seventh National Congress of CPC', 'event', '**Location:** Yan''an, China | **People:** Mao Zedong, Liu Shaoqi, Zhou Enlai — Formally adopted Mao Zedong Thought as guiding ideology alongside Marxism-Leninism. Prepared the party for the final confrontation with the Kuomintang. CPC membership had grown from ~40,000 in 1937 to over 1.2 million.', NULL, NULL),
  ('Shanghai Massacre', 'event', '**Location:** Shanghai, China | **People:** Chiang Kai-shek, Joseph Stalin — Chiang Kai-shek''s forces slaughtered thousands of communists and trade unionists. Stalin''s policy of subordinating the CPC to the Kuomintang was directly responsible — the CPC had been ordered to maintain the alliance even as the right wing of the KMT prepared to strike. One of the most devastating consequences of Stalinist foreign policy.', NULL, NULL),
  ('Silk Weavers'' Revolt / Canuts', 'event', '**Location:** Lyon, France — First independent working-class uprising in modern history. Lyon silk weavers seized the city under "Live working or die fighting." The black flag was flown for the first time as a symbol of proletarian hunger. Suppressed by the French army, but demonstrated the working class was capable of independent political and military action, distinct from the bourgeoisie.', NULL, NULL),
  ('Sixth Congress of Comintern', 'event', '**Location:** Moscow, Soviet Union | **People:** Nikolai Bukharin, Joseph Stalin — Adopted "Third Period" theory: imminent revolutionary crisis predicted; social-democratic parties characterized as "social-fascist" — the main enemy. This ultra-left line would prove catastrophic in Germany, preventing a united front against Nazism.', NULL, NULL),
  ('Sixth National Congress of CPC', 'event', '**Location:** Moscow, Soviet Union | **People:** Qu Qiubai, Zhou Enlai — Only CPC congress held outside China. Held in Moscow under Comintern supervision. Endorsed peasant-based strategy while formally maintaining leading role of the proletariat.', NULL, NULL),
  ('Sixth Plenary Session of CPC Central Committee', 'event', '**Location:** Yan''an, China | **People:** Mao Zedong — Consolidated Mao''s leadership. Mao called for "sinification of Marxism" — adapting communist theory to Chinese conditions.', NULL, NULL),
  ('Spanish Civil War Begins', 'event', '**Location:** Spain | **People:** Francisco Franco — Workers defeat Franco''s coup in Barcelona and Madrid. Anarchist (CNT-FAI) and POUM militias form. "¡No pasarán!" The Spanish Civil War became the great cause of the international left — the last stand against fascism before world war.', NULL, NULL),
  ('Spartacist Uprising', 'event', '**Location:** Berlin, Germany | **People:** Rosa Luxemburg, Karl Liebknecht, Gustav Noske — KPD attempts insurrection. Rosa Luxemburg and Karl Liebknecht murdered by Freikorps on orders of SPD Minister Noske. "Order reigns in Berlin!" — Luxemburg''s last article quoted the phrase to predict future revolution.', NULL, NULL),
  ('Storming of the Bastille', 'event', '**Location:** Paris, France | **People:** Louis XVI — The *sans-culottes* stormed the Bastille, symbol of royal absolutism, marking the symbolic beginning of the French Revolution. The intervention of the Parisian crowd made the revolution irreversible. The revolution abolished feudal privileges, declared the Rights of Man, and ultimately executed the king — sending shockwaves across every European monarchy.', NULL, NULL),
  ('The Eighteenth Brumaire', 'event', '**Location:** London, England | **People:** Karl Marx — Marx''s masterpiece of historical analysis. "History repeats itself, first as tragedy, then as farce." Introduces *Bonapartism* — where the executive achieves apparent independence from all classes. Develops the concept of the "dictatorship of the proletariat" as the necessary political form of transition.', NULL, NULL),
  ('The Great Betrayal', 'event', '**Location:** Berlin, Germany | **People:** Vladimir Lenin, Karl Kautsky — SPD votes unanimously for war credits. Second International collapses into social-chauvinism. Lenin initially refused to believe the news: "From now on, I am not a Social Democrat, I am a Communist." Demonstrated that decades of reformism had organically integrated socialist parties into the bourgeois state.', NULL, NULL),
  ('The Great Terror', 'event', '**Location:** Moscow, Soviet Union | **People:** Joseph Stalin, Grigory Zinoviev, Nikolai Bukharin — Stalin liquidated Old Bolsheviks. Zinoviev, Kamenev, Bukharin executed after show trials. Red Army decimated (Tukhachevsky). The generation that had made the October Revolution was physically annihilated by the counter-revolution from within.', NULL, NULL),
  ('The October Revolution', 'event', '**Location:** Petrograd, Russia | **People:** Vladimir Lenin, Leon Trotsky — First successful proletarian revolution. Bolsheviks seize Winter Palace. Second Congress of Soviets ratifies transfer of power. Lenin: "We shall now proceed to construct the socialist order." Transformed Marxism from theory into reality, inspiring movements worldwide.', NULL, NULL),
  ('The Paris Commune Begins', 'event', '**Location:** Paris, France | **People:** Karl Marx — First workers'' government in history. Abolished the standing army, made all officials elected and recallable, paid them workers'' wages. Marx: "The working class cannot simply lay hold of the ready-made state machinery and wield it for its own purposes." Lasted 72 days.', NULL, NULL),
  ('The Springtime of Nations', 'event', '**Location:** Europe | **People:** Karl Marx, Friedrich Engels — Revolutions erupted across Europe. Marx and Engels edited the *Neue Rheinische Zeitung* in Cologne as "the extreme left wing of democracy." Revealed that the bourgeoisie, confronted with proletarian demands, would ally with the old order. Provided material for Marx''s most penetrating historical analyses.', NULL, NULL),
  ('Third Congress of Comintern', 'event', '**Location:** Moscow, Soviet Russia | **People:** Vladimir Lenin, Leon Trotsky — Repudiated "theory of the offensive" after disastrous German March Action. Adopted watchword "To the masses!" — communist parties must win workers'' confidence before attempting revolution.', NULL, NULL),
  ('Third International Founded', 'event', '**Location:** Moscow, Soviet Russia | **People:** Vladimir Lenin, Grigory Zinoviev — Lenin founds Communist International (Comintern). The call goes out for world revolution. Intended to replace the bankrupt Second International with a revolutionary organization that would coordinate communist parties worldwide.', NULL, NULL),
  ('Third National Congress of CPC', 'event', '**Location:** Guangzhou, China | **People:** Chen Duxiu, Mao Zedong — Adopted decision for CPC members to join the Kuomintang as individuals — "bloc within" united front strategy directed by the Comintern against imperialism and warlordism.', NULL, NULL),
  ('Thirteenth Plenum of ECCI', 'event', '**Location:** Moscow, Soviet Union — Analyzed fascism as "the open terrorist dictatorship of the most reactionary, most chauvinistic and most imperialist elements of finance capital." Formulation later refined at the Seventh Congress.', NULL, NULL),
  ('Three Great Campaigns', 'event', '**Location:** Manchuria/North China | **People:** Mao Zedong, Lin Biao, Chen Yi, Deng Xiaoping — Liaoshen, Huaihai, and Pingjin campaigns (Sep 1948 – Jan 1949) were the decisive battles. CPC destroyed the main Nationalist armies, gaining control of Manchuria, the Yangtze-Huai region, and North China including Beijing and Tianjin.', NULL, NULL),
  ('Treaty of Brest-Litovsk', 'event', '**Location:** Brest-Litovsk | **People:** Vladimir Lenin, Leon Trotsky — Harsh peace with Germany. Soviet Russia exits WWI. Left SRs revolt. Lenin argues the revolution needs a "breathing space." Surrendered vast territories (Finland, Baltic states, Poland, Ukraine) to preserve the revolution.', NULL, NULL),
  ('Trotsky Exiled to Alma-Ata', 'event', '**Location:** Alma-Ata, Kazakhstan | **People:** Leon Trotsky, Joseph Stalin — Left Opposition crushed in the USSR. Trotsky exiled to Kazakhstan, then expelled from the Soviet Union entirely in 1929. Spent his remaining years organizing the Fourth International and writing critical analyses of Stalinism.', NULL, NULL)
INSERT INTO glossary (term, type, explanation, url, related_terms) VALUES
  ('Trotsky Removed as Military Commissar', 'event', '**Location:** Moscow, Soviet Union | **People:** Leon Trotsky, Joseph Stalin — Trotsky lost his primary institutional base of power. Decisive moment in the internal party struggle following Lenin''s death. Beginning of the systematic dismantling of the Left Opposition.', NULL, NULL),
  ('Wall Street Crash', 'event', '**Location:** New York, USA — Triggered the Great Depression — worst economic crisis in capitalist history. Mass unemployment, bank failures, industrial collapse worldwide. Vindicated Marxist analysis of capitalism''s contradictions. Created conditions for the rise of fascism in Europe.', NULL, NULL),
  ('What Is To Be Done?', 'event', '**Location:** Stuttgart, Germany | **People:** Vladimir Lenin — Foundational work on revolutionary party organization. Against "Economism": revolutionary consciousness must be brought to the class by a vanguard of professional revolutionaries. Established theoretical basis for the Bolshevik party conception.', NULL, NULL),
  ('World War I Armistice', 'event', '**Location:** Compiègne, France — Armistice signed in a railway carriage. 17+ million dead, old European order in ruins. Created conditions for revolutionary upheaval across the continent.', NULL, NULL),
  ('World War I Begins', 'event', '**Location:** Europe — Assassination of Archduke Franz Ferdinand triggered a chain of alliances plunging Europe into war. Over 17 million killed, four empires destroyed (Russian, German, Austro-Hungarian, Ottoman). For Marxists: inevitable product of inter-imperialist rivalry — competition between national capitals for markets and spheres of influence.', NULL, NULL),
  ('World War II Begins in Europe', 'event', '**Location:** Poland | **People:** Adolf Hitler — Germany invaded Poland. Britain and France declare war. The conflict would kill 70–85 million people and fundamentally reshape the world order.', NULL, NULL),
  ('Wuhan KMT Expels Communists', 'event', '**Location:** Wuhan, China | **People:** Wang Jingwei — First United Front collapsed completely. The "left" KMT faction also expelled all communists. CPC driven underground and into the countryside. Complete vindication of those who had warned against the "bloc within" strategy.', NULL, NULL),
  ('Xi''an Incident', 'event', '**Location:** Xi''an, China | **People:** Chiang Kai-shek, Zhang Xueliang, Zhou Enlai — Chiang Kai-shek detained by his own generals demanding an end to civil war and a united front against Japan. Zhou Enlai negotiated for the CPC. Chiang released after agreeing to cooperate. Led to the Second United Front.', NULL, NULL),
  ('Yan''an Rectification Movement', 'event', '**Location:** Yan''an, China | **People:** Mao Zedong — Mass ideological campaign to consolidate Mao''s leadership and establish Mao Zedong Thought as the party''s guiding ideology. Combined study, criticism, and self-criticism. Set the pattern for future CPC political campaigns.', NULL, NULL),
  ('Zimmerwald Conference', 'event', '**Location:** Zimmerwald, Switzerland | **People:** Vladimir Lenin, Leon Trotsky — Anti-war socialists meet. Lenin organizes the Zimmerwald Left: "Turn the imperialist war into civil war." Nucleus of the future Third International. Lenin: "All the internationalists in the world could fit in two stagecoaches."', NULL, NULL),
  ('Zunyi Conference', 'event', '**Location:** Zunyi, China | **People:** Mao Zedong, Zhou Enlai, Wang Jiaxiang — Turning point in CPC history during the Long March. Mao gained effective control of military decision-making, displacing Comintern-backed leadership that had led to disastrous defeats. Beginning of Mao''s ascendancy.', NULL, NULL)
INSERT INTO glossary (term, type, explanation, url, related_terms) VALUES
  ('Absolute Rent', 'concept', '(German: Absolute Grundrente) — Rent paid to landowners regardless of land quality, arising from private land ownership monopoly', NULL, NULL),
  ('Abstract Labour', 'concept', '(German: Abstrakte Arbeit) — Human labour considered purely as expenditure of labour-power, creating value in commodities', NULL, NULL),
  ('Accumulation', 'concept', '(German: Akkumulation) — The process of capital expansion through reinvestment of surplus value', NULL, NULL),
  ('Active Army of Labour', 'concept', '(German: Aktive Armee der Arbeit) — Employed workers as distinct from the reserve army of unemployed', NULL, NULL),
  ('Agitation', 'concept', 'Political work arousing masses to action based on specific grievances', NULL, NULL),
  ('Agrarian Question', 'concept', '(German: Agrarfrage) — The relationship between capitalism and agricultural production, including peasant classes', NULL, NULL),
  ('Alienation', 'concept', '(German: Entfremdung) — The separation of workers from their labour, products, fellow humans, and human essence', NULL, NULL),
  ('Analytical Marxism', 'concept', '(German: Analytischer Marxismus) — School applying analytic philosophy methods to Marxist theory', NULL, NULL),
  ('Anarchism', 'concept', '(German: Anarchismus) — Political philosophy opposing all state authority, often in tension with Marxism', NULL, NULL),
  ('Ancient Mode of Production', 'concept', '(German: Antike Produktionsweise) — Slave-based mode of production characteristic of classical antiquity', NULL, NULL),
  ('Anti-Colonialism', 'concept', '(German: Antikolonialismus) — Opposition to colonial domination, linked to proletarian internationalism', NULL, NULL),
  ('Antithesis', 'concept', '(German: Antithese) — In dialectics, the opposing force or stage that contradicts the thesis', NULL, NULL),
  ('Apartheid', 'concept', 'System of racial segregation analyzed through Marxist lens of super-exploitation', NULL, NULL),
  ('Appeasement', 'concept', '(German: Beschwichtigungspolitik) — Policy of conciliating aggressors, criticized by Marxists as strengthening imperialism', NULL, NULL),
  ('Appropriation', 'concept', '(German: Aneignung) — The capitalist seizure of surplus value produced by workers', NULL, NULL),
  ('Arbeiterklasse', 'concept', 'Working class; those who sell labour-power for wages', NULL, NULL),
  ('Arbeitskraft', 'concept', 'Labour-power; the commodity workers sell to capitalists', NULL, NULL),
  ('Arbeitslohn', 'concept', 'Wages; the price of labour-power', NULL, NULL),
  ('Arbeitsprozess', 'concept', 'Labour-process; the activity of producing use-values', NULL, NULL),
  ('Arbeitszeit', 'concept', 'Working-time; divided into necessary and surplus labour-time', NULL, NULL),
  ('Aristocracy of Labour', 'concept', '(German: Arbeiteraristokratie) — Privileged stratum of workers benefiting from imperialism', NULL, NULL),
  ('Artificial Intelligence', 'concept', '(German: Künstliche Intelligenz) — Contemporary topic analyzed through Marxist lens of automation and labour', NULL, NULL),
  ('Assertion', 'concept', '(German: Behauptung) — In logic, a statement affirmed as true', NULL, NULL),
  ('Association', 'concept', '(German: Assoziation) — Free association of producers in communist society', NULL, NULL),
  ('Atheism', 'concept', '(German: Atheismus) — Rejection of religious belief; Marxism adopts materialist atheism', NULL, NULL),
  ('Atomism', 'concept', '(German: Atomismus) — Method treating society as collection of individuals, opposed by Marxism', NULL, NULL),
  ('Austro-Marxism', 'concept', '(German: Austromarxismus) — School of Marxism developed in Austria (Adler, Renner, Hilferding)', NULL, NULL),
  ('Authority', 'concept', '(German: Autorität) — Power to command; analyzed in relation to class power', NULL, NULL),
  ('Automation', 'concept', '(German: Automatisierung) — Mechanization of production, affecting labour and value', NULL, NULL),
  ('Autonomy', 'concept', '(German: Autonomie) — Relative independence, e.g., of superstructure from base', NULL, NULL),
  ('Avant-Garde', 'concept', '(German: Avantgarde) — See Vanguard', NULL, NULL),
  ('Balance of Trade', 'concept', '(German: Handelsbilanz) — Difference between exports and imports in capitalist economy', NULL, NULL),
  ('Bank Capital', 'concept', '(German: Bankkapital) — Capital employed in banking, distinct from industrial capital', NULL, NULL),
  ('Barter', 'concept', '(German: Tauschhandel) — Direct exchange of commodities without money', NULL, NULL),
  ('Base and Superstructure', 'concept', '(German: Basis und Überbau) — Economic foundation determines political/ideological superstructure [[26,69]]', NULL, NULL),
  ('Basic Wage', 'concept', '(German: Grundlohn) — Minimum wage necessary for worker subsistence', NULL, NULL),
  ('Bauer', 'concept', 'Peasant; small agricultural producer', NULL, NULL),
  ('Bauernbefreiung', 'concept', 'Emancipation of peasants from feudal obligations', NULL, NULL),
  ('Bedürfnis', 'concept', 'Need; human requirements satisfied through production', NULL, NULL),
  ('Begriff', 'concept', 'Concept; in Hegelian-Marxist dialectics', NULL, NULL),
  ('Bekämpfung', 'concept', 'Struggle against; e.g., class enemy', NULL, NULL),
  ('Bewegungsform', 'concept', 'Form of motion; in dialectical materialism', NULL, NULL),
  ('Bewusstsein', 'concept', 'Consciousness; determined by social being', NULL, NULL),
  ('Bilanz', 'concept', 'Balance sheet; in capitalist accounting', NULL, NULL),
  ('Bimetallismus', 'concept', 'Monetary system using gold and silver', NULL, NULL),
  ('Bodenrente', 'concept', 'Ground rent; see Rent', NULL, NULL),
  ('Bourgeois', 'concept', 'Capitalist class member; owner of means of production', NULL, NULL),
  ('Bourgeois Democracy', 'concept', '(German: Bürgerliche Demokratie) — Democratic forms serving capitalist class rule', NULL, NULL),
  ('Bourgeois Ideology', 'concept', '(German: Bürgerliche Ideologie) — Ruling ideas of capitalist class presented as universal', NULL, NULL),
  ('Bourgeois Revolution', 'concept', '(German: Bürgerliche Revolution) — Revolution establishing capitalist rule (e.g., French 1789)', NULL, NULL)
INSERT INTO glossary (term, type, explanation, url, related_terms) VALUES
  ('Bourgeois Right', 'concept', '(German: Bürgerliches Recht) — Rights formalized under capitalism, persisting in early socialism', NULL, NULL),
  ('Bourgeois Socialism', 'concept', '(German: Bourgeoiser Sozialismus) — Reformist socialism preserving capitalism', NULL, NULL),
  ('Bourgeoisie', 'concept', '(German: die Bourgeoisie) — Capitalist class owning means of production [[69,140]]', NULL, NULL),
  ('Bruttoinlandsprodukt', 'concept', 'Gross domestic product; capitalist economic measure', NULL, NULL),
  ('Business Cycle', 'concept', '(German: Geschäftszyklus) — Periodic fluctuations in capitalist economy', NULL, NULL),
  ('Bäuerliche Frage', 'concept', 'See Agrarian Question', NULL, NULL),
  ('Börsenkapital', 'concept', 'Stock exchange capital; finance capital', NULL, NULL),
  ('Bürokratie', 'concept', 'Bureaucracy; administrative apparatus of state', NULL, NULL),
  ('Cadre', 'concept', '(German: Kader) — Ideologically trained elite for leadership positions', NULL, NULL),
  ('Capital', 'concept', '(German: Kapital) — Self-expanding value; means of production as social relation', NULL, NULL),
  ('Capital Accumulation', 'concept', '(German: Kapitalakkumulation) — See Accumulation', NULL, NULL),
  ('Capital Centralization', 'concept', '(German: Kapitalzentralisation) — Merging of existing capitals through competition/credit', NULL, NULL),
  ('Capital Circulation', 'concept', '(German: Kapitalzirkulation) — Movement of capital through production and exchange', NULL, NULL),
  ('Capital Concentration', 'concept', '(German: Kapitalkonzentration) — Growth of individual capitals through accumulation', NULL, NULL),
  ('Capital Export', 'concept', '(German: Kapitalexport) — Investment of capital abroad; feature of imperialism', NULL, NULL),
  ('Capital Flight', 'concept', '(German: Kapitalflucht) — Rapid withdrawal of capital from country/region', NULL, NULL),
  ('Capital Intensity', 'concept', '(German: Kapitalintensität) — Ratio of capital to labour in production', NULL, NULL),
  ('Capitalist', 'concept', '(German: Kapitalist) — Owner of capital employing wage-labour', NULL, NULL),
  ('Capitalist Crisis', 'concept', '(German: Kapitalistische Krise) — Periodic economic crises inherent to capitalism', NULL, NULL),
  ('Capitalist State', 'concept', '(German: Kapitalistischer Staat) — State serving capitalist class interests [[3,168]]', NULL, NULL),
  ('Category', 'concept', '(German: Kategorie) — Conceptual form in Marxist theory', NULL, NULL),
  ('Cause', 'concept', '(German: Ursache) — In dialectics, related to effect', NULL, NULL),
  ('Centralization', 'concept', '(German: Zentralisation) — See Capital Centralization', NULL, NULL),
  ('Chauvinism', 'concept', '(German: Chauvinismus) — Aggressive nationalism; "social-chauvinist" betrays workers', NULL, NULL),
  ('Circulation', 'concept', '(German: Zirkulation) — Movement of commodities and capital', NULL, NULL),
  ('Class', 'concept', '(German: Klasse) — Group defined by relation to means of production', NULL, NULL),
